SELECT d_year, i_category, COUNT(*) AS order_count FROM ( SELECT d.d_year AS d_year, i.i_category AS i_category, ws.ws_net_paid AS ws_net_paid FROM web_sales ws JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk JOIN item i ON ws.ws_item_sk = i.i_item_sk JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE d.d_year = 1917 AND i.i_brand = 'corpbrand #6                                      ' AND sm.sm_type = 'OVERNIGHT                     ' ) sub GROUP BY d_year, i_category HAVING AVG(ws_net_paid) > 2697.00
